import { Hono } from 'hono';
import type { AdapterBundle } from '../../contracts.js';
import { session } from '../../session.js';

export function registerLegacyChatRoutes(app: Hono, adapters: AdapterBundle): void {
  // Old web bundles still expect `items`.
  app.get('/v1/chats/legacy', async (c) => {
    const chats = await adapters.store.listChats(session(c).userId);
    return c.json({ items: chats });
  });
}
